  const{error}=await supabase.rpc('member_pay_winning_item_payment',{p_payment_id:paymentId,p_idempotency_key:key});
  if(error){if(/insufficient/i.test(error.message))throw new Error('Insufficient Funds – Please Add Funds');throw error;}
