  allActivations.forEach(x=>rows.push(['Package activation',x.submitted_at,x.package?.name||x.id,String(x.amount_paid),x.currency,x.activation_status+'/'+x.payment_status,'Activation #'+x.activation_number+' · UTR '+(x.payment_reference||'Not recorded')+' · Bid Wallet credit '+money(Number(x.bid_wallet_credit||0),x.currency||'INR')+' · Reviewed '+(x.verified_at||'Pending')]));
  allBids.forEach(x=>rows.push(['Auction bid',x.created_at,x.auction?.title||x.id,String(x.bid_amount),'INR',x.status,'Auction status: '+(x.auction?.status||'Unavailable')]));
  allFixedBids.forEach(x=>rows.push(['Fixed Bid entry',x.created_at,x.campaign?.title||x.id,String(x.bid_amount),'INR',x.status,'Campaign status: '+(x.campaign?.status||'Unavailable')]));
